cd /Users/michelkerkmeester/MEGA/Development/Code_Environment/Public && P=specs/system-speckit/054-weak-model-spec-authoring/006-speckit-command-and-agent-alignment && python3 - "$P" <<'PY'
import json, re, sys
p=sys.argv[1]
rows=[json.loads(l) for l in open(p+'/tasks.md') if l.startswith('{"id"')]
plan=open(p+'/plan.md').read()
table={m[0]:(int(m[2]),m[1]) for m in re.findall(r'^\| (R-\d{3}) \| `([^`]+)` \| (\d+) \|', plan, re.M)}
hdr={m[0]:(m[1],int(m[2])) for m in re.findall(r'^\*\*(R-\d{3})\*\* `[A-Z0-9]+` (?:CHANGE|MIRROR) `([^`]+):(\d+)`$', plan, re.M)}
print('rows',len(rows),'table',len(table),'headers',len(hdr))
bad=[]
for r in rows:
    t=open(r['file']).read()
    if r['locator'] not in t:
        bad.append((r['id'],'locator missing')); continue
    n=t[:t.index(r['locator'])].count('\n')+1
    if table.get(r['id'])!=(n,r['file']): bad.append((r['id'],'table',table.get(r['id']),(n,r['file'])))
    if hdr.get(r['id'])!=(r['file'],n): bad.append((r['id'],'header',hdr.get(r['id']),(r['file'],n)))
print('mismatches',bad)
PY

